import sys
from atcoder.lazysegtree import LazySegTree

input = sys.stdin.buffer.readline

def op(a, b):
    return (a[0] + b[0], a[1] + b[1])

def mapping(f, x):
    return (x[0] + f * x[1], x[1])

def composition(f, g):
    return f + g

n, m, q = map(int, input().split())
lr = [tuple(map(int, input().split())) for _ in range(n)]

qs = [[] for _ in range(n + 1)]
for i in range(q):
    u, d, l, r = map(int, input().split())
    qs[d].append((l - 1, r, i, 1))
    qs[u - 1].append((l - 1, r, i, -1))

seg = LazySegTree(op, (0, 0), mapping, composition, 0, [(0, 1)] * m)

ans = [0] * q
for x in range(n + 1):
    if x:
        l, r = lr[x-1]
        seg.apply(l - 1, r, 1)

    for l, r, i, sgn in qs[x]:
        ans[i] += sgn * seg.prod(l, r)[0]

print(*ans, sep="\n")
